/* Hanken Grotesk Font Family */
@font-face {
  font-family: 'Hanken Grotesk';
  src: url('HankenGrotesk-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --font-hanken-grotesk: 'Hanken Grotesk', sans-serif;
  --clr-primary: #445566;
  --clr-primary-foreground: #ffffff;
  --clr-accent: #e9c7f3;
  --clr-accent-foreground: #4a325b;
  --clr-secondary: #2C6F52;
  --clr-background-light: #3b4d4b;
  --clr-card-light: #ffffff;
  --clr-primary-muted: #5d7374;
  --clr-primary-light: #a9c1b8;
  --clr-black: #182021;
  --clr-white: #f2f2f3;
  --clr-muted: #626C84
  --clr-gray-400: #99a1af;
  --clr-gray-600: #4a5565;
  --clr-gray-800: #1e2939;
  --clr-gray-900: #101828;
}

*, ::after, ::before {
  box-sizing: border-box;
  border-width: 0;
  border-style: solid;
  border-color: #e5e7eb;
}

button, input {
  -webkit-appearance: button;
  background-color: transparent;
  background-image: none;
  text-transform: none;

  font-size: 100%;
  font-family: inherit;
  font-feature-settings: inherit;
  font-variation-settings: inherit;
  font-weight: inherit;
  line-height: inherit;

  margin: 0;
  padding: 0;
}

h1 {
  font-size: inherit;
  font-weight: inherit;
}

h1, p {
  margin: 0;
}

a {
  color: inherit;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

body {
  font-family: var(--font-hanken-grotesk);
  color: var(--clr-primary);
  height: 100dvh;
  min-height: max(884px, 100dvh);
  width: 100%;
  overflow: none;
}

.material-symbols-outlined {
  font-family: 'Material Symbols Outlined';
  font-weight: normal;
  font-style: normal;
  font-size: 24px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;

  /* text-lg */
  font-size: 1.125rem;
  line-height: 1.5rem;
}

.relative {
  position: relative;
}

.absolute {
  position: absolute;
}

.space-y-6 {
  :where(& > :not(:last-child)) {
    --tw-space-y-reverse: 0;
    --spacing: 0.25rem;
    margin-block-start: calc(calc(var(--spacing) * 6) /* 1.5rem = 24px */ * var(--tw-space-y-reverse));
    margin-block-end: calc(calc(var(--spacing) * 6) /* 1.5rem = 24px */ * calc(1 - var(--tw-space-y-reverse)));
  }
}
.antialiased {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}


.card-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  inset: 0;
  padding: 24px;
  height: 100%;
  min-width: 400px;
  max-width: 500px;
  width: 100%;
  margin: auto;
  vertical-align: middle;
  overflow: auto;
}

.card {
  background-color: var(--clr-card-light);
  padding: 32px;
  transition: all;
  transition-duration: 300ms;
  border-radius: 32px;
}

footer {
  margin-top: 38px;
  text-align: center;

}
.footer-copyright {
  margin-top: 16px;
  font-size: 10px;
  color: var(--clr-primary);
  text-transform: uppercase;
  letter-spacing: 0.1rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  column-gap: 8px;
  row-gap: 4px;
  font-size: 10px;
  color: var(--clr-secondary);
  font-weight: 500;

  a {
    text-decoration: none;
    display: inline-flex;
    gap: 4px;

    &:hover {
      color: var(--clr-gray-600);
      text-decoration: underline;
    }
  }
  a::after {
    content: url("data:image/svg+xml,%3Csvg width='12' height='12' viewBox='0 0 12 12' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M6.59995 1.65001C6.59995 1.89939 6.80058 2.10001 7.04995 2.10001H9.26433L4.93308 6.43126C4.75683 6.60751 4.75683 6.89251 4.93308 7.06689C5.10933 7.24126 5.39433 7.24314 5.5687 7.06689L9.89995 2.73564V4.95001C9.89995 5.19939 10.1006 5.40001 10.35 5.40001C10.5993 5.40001 10.8 5.19939 10.8 4.95001V1.65001C10.8 1.40064 10.5993 1.20001 10.35 1.20001H7.04995C6.80058 1.20001 6.59995 1.40064 6.59995 1.65001ZM2.69995 3.00001C1.8712 3.00001 1.19995 3.67126 1.19995 4.50001V9.30001C1.19995 10.1288 1.8712 10.8 2.69995 10.8H7.49995C8.3287 10.8 8.99995 10.1288 8.99995 9.30001V7.65001C8.99995 7.40064 8.79933 7.20001 8.54995 7.20001C8.30058 7.20001 8.09995 7.40064 8.09995 7.65001V9.30001C8.09995 9.63189 7.83183 9.90001 7.49995 9.90001H2.69995C2.36808 9.90001 2.09995 9.63189 2.09995 9.30001V4.50001C2.09995 4.16814 2.36808 3.90001 2.69995 3.90001H4.34995C4.59933 3.90001 4.79995 3.69939 4.79995 3.45001C4.79995 3.20064 4.59933 3.00001 4.34995 3.00001H2.69995Z' fill='%232C6F52'/%3E%3C/svg%3E%0A");
    width: 12px;
    height: 12px;
  }
}

.logo-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 40px;

  .logo {
    display: flex;
    align-items: center;
  }
}

.card-contents {
  display: flex;
  flex-direction: column;
  gap: 44px;
  padding-block: 32px;
}

.card-header {
  font-size: 48px;
  line-height: 31px;
  font-weight: 700;
}

.card-contents-description {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.text-3xl {
  font-size: 24px;
  line-height: 31px;
  font-weight: 700;
  letter-spacing: 0;
}

.text-lg {
  font-size: 16px;
  line-height: 22px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--clr-muted);
}

button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;

    width: 100%;
    padding-inline: 16px;
    padding-block: 8px;
    height: 44px;
    background-color: var(--clr-primary);
    color: var(--clr-primary-foreground);
    border: none;
    cursor: pointer;
    transition: background-color 200ms ease-in-out;
    border-radius: calc(infinity * 1px);

    transition-property: all;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
    transition-duration: 200ms;

    &:active {
      scale: 0.98;
    }

    &:hover {
      @media (hover: hover) {
        opacity: 90%;
      }
    }
}

/* Background image */
.chapsvision-bg {
  height: 100%;
  width: 100%;
  background-color: #3b4d4b;
  background-image: url('data:image/jpeg;base64,');
  overflow: hidden;
}
